import{_ as t,o,c as i,a2 as s}from"./chunks/framework.CyZTVJbV.js";const f=JSON.parse('{"title":"OIDC Federation Dogfood — id-token-verify quality report","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/auth/oidc-federation-id-token.md","filePath":"quality-reports/auth/oidc-federation-id-token.md"}'),a={name:"quality-reports/auth/oidc-federation-id-token.md"};function r(d,e,c,n,h,l){return o(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="oidc-federation-dogfood-—-id-token-verify-quality-report" tabindex="-1">OIDC Federation Dogfood — id-token-verify quality report <a class="header-anchor" href="#oidc-federation-dogfood-—-id-token-verify-quality-report" aria-label="Permalink to &quot;OIDC Federation Dogfood — id-token-verify quality report&quot;">​</a></h1><p>id_token-layer report for <code>examples/dogfood-oidc-federation</code> Sub-Issue #874 (v1.21-4c). Extends the DCR report (<code>oidc-federation-dcr.md</code>, Sub-Issue #873) with the OpenID Connect Core 1.0 §3.1.3.6-§3.1.3.7 id_token verification fidelity harness. Sub-Issue #875 (Federation trust chain + JWKS rotation e2e) layers the final fidelity axes on top.</p><h2 id="fidelity-axes-id-token-verify" tabindex="-1">Fidelity axes (id-token-verify) <a class="header-anchor" href="#fidelity-axes-id-token-verify" aria-label="Permalink to &quot;Fidelity axes (id-token-verify)&quot;">​</a></h2><p>The id-token-verify harness lifts the harness from 8 → 12 axes. Axes 1–4 stay covered by the Sub-Issue #872 skeleton report (<code>discovery-jwks-skeleton.spec.ts</code>); axes 5–8 are the DCR-layer additions from Sub-Issue #873; axes 9–12 are the id_token-layer additions this Sub-Issue lands.</p><table tabindex="0"><thead><tr><th>axis</th><th>mock (<code>@kiwa-lab/auth</code> via <code>src/lib/id-token.ts</code> wrapper)</th><th>real (Keycloak, <code>OIDC_BOOTSTRAP=1</code>, Sub-Issue #875)</th><th>assertion</th></tr></thead><tbody><tr><td>9. JWS signature</td><td>header + payload + kid recompute must match the signature segment; wrong kid, tampered signature, missing / unknown kid, alg mismatch all refuse with <code>axis=signature</code>. Rotated-but-in-retention-window kid still verifies.</td><td>Keycloak <code>/token</code> mints RS256 / ES256 signed id_tokens; the RP verifies against Keycloak&#39;s <code>/certs</code> JWKS.</td><td>OIDC Core 1.0 §3.1.3.7 — the RP MUST validate the JWS per RFC 7515 §5.2, using the kid selected from the JWKS.</td></tr><tr><td>10. claims 一致</td><td>iss / aud MUST match the RP expectations; exp within skew tolerance (default 60 s) accepts, beyond skew refuses; iat in the future beyond skew refuses (clock-drift attack).</td><td>Keycloak mints claims from realm settings; the RP verifies against the expected iss + client_id.</td><td>OIDC Core 1.0 §3.1.3.7 — the RP MUST verify iss / aud + reject expired / future-dated tokens.</td></tr><tr><td>11. nonce echo</td><td><code>expectedNonce</code> supplied to the wrapper is compared against the <code>nonce</code> claim; mismatch refuses with <code>axis=nonce</code>; missing claim when expectation is present refuses.</td><td>Keycloak echoes the authorization-request <code>nonce</code> into the id_token when supplied.</td><td>OIDC Core 1.0 §3.1.2.1 — when the RP sends <code>nonce</code> on <code>/authorize</code>, the OP MUST echo it in the id_token; the RP MUST verify the echo (replay defence).</td></tr><tr><td>12. hash chain</td><td><code>at_hash</code> = SHA-256(access_token)[0..15] base64url; <code>c_hash</code> = SHA-256(code)[0..15] base64url; mismatch on either refuses with <code>axis=hash_chain</code>. <code>computeTokenHash</code> produces a fixed 22-char base64url string.</td><td>Keycloak follows the same recipe per OIDC Core §3.1.3.6 for <code>at_hash</code> and §3.3.2.11 for <code>c_hash</code>.</td><td>OIDC Core 1.0 §3.1.3.6 + §3.3.2.11 — id_token hash claims bind the token to the access_token + code the RP received so an attacker cannot substitute a different pair.</td></tr></tbody></table><h2 id="test-coverage" tabindex="-1">Test coverage <a class="header-anchor" href="#test-coverage" aria-label="Permalink to &quot;Test coverage&quot;">​</a></h2><ul><li><code>tests/id-token-verify.spec.ts</code> — 20 tests, split into six describe blocks: <ul><li><code>axis 1 — JWS signature</code> — 4 tests: fresh signed accept, tampered signature refuse, unknown kid refuse, rotated-but-in-window accept.</li><li><code>axis 2 — claims 一致</code> — 5 tests: iss mismatch refuse, aud mismatch refuse, exp beyond skew refuse, exp within skew accept, iat in the future refuse.</li><li><code>axis 3 — nonce echo</code> — 3 tests: nonce echo accept, nonce mismatch refuse, RP expects nonce but claim absent refuse.</li><li><code>axis 4 — hash chain</code> — 4 tests: at_hash + c_hash accept, at_hash mismatch refuse, c_hash mismatch refuse, computeTokenHash 22-char base64url anchor.</li><li><code>mustVerifyIdToken (throwing wrapper)</code> — 2 tests: returns claims on success, throws <code>IdTokenVerifyError</code> with structured issue on failure.</li><li><code>parseIdTokenHeader</code> — 3 tests: returns alg + kid, throws structural on 2-segment token, throws signature-axis on header without kid.</li></ul></li></ul><p>Total 20 tests exceeds the 12+ AC threshold. Behavioural coverage on the underlying <code>createIdTokenSigner.verify</code> lives inside <code>packages/auth/tests/setup-oidc-env.test.ts</code> (35 tests per PR #855); this report tracks the wrapper layer + fidelity harness.</p><h2 id="wrapper-contract" tabindex="-1">Wrapper contract <a class="header-anchor" href="#wrapper-contract" aria-label="Permalink to &quot;Wrapper contract&quot;">​</a></h2><p>The dogfood-specific behaviour lives entirely in <code>src/lib/id-token.ts</code> —</p><ul><li><code>verifyIdToken(verifier, jwt, options)</code> — discriminated outcome (<code>{ ok: true; claims } | { ok: false; issue: { axis, reason } }</code>). The verifier is injected as a parameter so <code>env.verifyIdToken</code> (mock) and a Keycloak-backed verifier can share the same wrapper without touching the axis classifier.</li><li><code>classifyVerifyReason(reason)</code> — folds the underlying verifier&#39;s raw reason string onto one of the axis tags (<code>signature</code> / <code>claims</code> / <code>nonce</code> / <code>hash_chain</code> / <code>structural</code>) so tests pin the failure surface without regexing.</li><li><code>mustVerifyIdToken(verifier, jwt, options)</code> — throwing variant used by the RP callback path where any failure produces an HTTP 401. Throws <code>IdTokenVerifyError</code> carrying the same structured <code>IdTokenVerifyIssue</code>.</li><li><code>parseIdTokenHeader(jwt)</code> — extracts alg + kid from the JWT header without invoking the verifier so the RP can look up the matching JWKS key first. Throws structural error for malformed JWTs; throws signature-axis error for headers missing kid.</li></ul><h2 id="rp-wiring-nuxt-3-skeleton" tabindex="-1">RP wiring (Nuxt 3 skeleton) <a class="header-anchor" href="#rp-wiring-nuxt-3-skeleton" aria-label="Permalink to &quot;RP wiring (Nuxt 3 skeleton)&quot;">​</a></h2><p>Sub-Issue #874 lands the Nuxt 3 RP skeleton under <code>rp/</code>. The RP —</p><ul><li><code>pages/index.vue</code> — &quot;Sign in&quot; button + userinfo panel driven by <code>/api/userinfo</code> and <code>/api/authorize</code> calls.</li><li><code>pages/callback.vue</code> — receives <code>?code=&amp;state=</code>, defers to <code>/api/callback</code> for the exchange, redirects to <code>/</code> on success.</li><li><code>server/api/authorize.get.ts</code> — builds the OIDC authorization URL (issuer + state + nonce + PKCE S256 challenge), stashes <code>state</code> / <code>nonce</code> / <code>code_verifier</code> on HttpOnly cookies for the callback.</li><li><code>server/api/callback.post.ts</code> — matches <code>state</code> (CSRF gate), exchanges the code for <code>access_token + id_token</code> via the OP&#39;s <code>/token</code>, calls <code>/userinfo</code> with the access_token, persists the userinfo on a session cookie. The id_token verification hook is annotated <code>TODO(v1.21-4d)</code> — the fidelity harness exercises the verifier path against the mock env directly; the JWKS-discovery-driven wiring lands in Sub-Issue #875.</li><li><code>server/api/userinfo.get.ts</code> — reads the userinfo cookie the callback wrote.</li></ul><p>The RP is <code>pnpm typecheck</code> clean (<code>nuxt prepare</code> regenerates <code>.nuxt/tsconfig.json</code> before <code>tsc --noEmit</code>). The full run-time exercise against a spawned OP (mock env booted as a Nitro sidecar + Playwright driving the browser) is scoped to Sub-Issue #875.</p><h2 id="environment-gating" tabindex="-1">Environment gating <a class="header-anchor" href="#environment-gating" aria-label="Permalink to &quot;Environment gating&quot;">​</a></h2><ul><li><code>KIWA_MODE=mock</code> — forces the mock env; every axis 9–12 test always runs. The verifier used is <code>env.verifyIdToken</code> from <code>setupOidcEnv</code>.</li><li><code>OIDC_BOOTSTRAP=1</code> — opt-in for real ceremonies. Sub-Issue #875 wires Keycloak <code>/token</code> + <code>/certs</code> so axes 9–12 diff against a real signer; until then the real driver stays refused via <code>KIWA_OIDC_ENV_MISSING</code> for id_token flows.</li></ul><h2 id="what-lands-in-the-successor" tabindex="-1">What lands in the successor <a class="header-anchor" href="#what-lands-in-the-successor" aria-label="Permalink to &quot;What lands in the successor&quot;">​</a></h2><ul><li><strong>Sub-Issue #875 (v1.21-4d — Federation + rotation e2e)</strong> lands the trust chain (3-level resolve + cycle detect + expiry) + JWKS rotation e2e (id_token signed under old kid stays verifiable until retention window elapses) + real Keycloak fidelity gate for id_token verify + integrated docs. Fidelity harness caps out at 16 axes.</li></ul>',19)])])}const p=t(a,[["render",r]]);export{f as __pageData,p as default};
